  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('8267c2bc-4fd2-5bb2-8ed2-d4fe34305047', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text with the most logical and precise word or phrase?', '["confused", "reluctant", "ineligible", "chosen"]'::jsonb, 1, 'The National Heritage Fellowship was created to honor exceptional folk and traditional artists in the United States. In 2013, the fellowship was given to the Pyramid Lake Paiute storyteller Ralph Burns. Burns was _____ to receive it because of his lifetime contributions to the arts.'),
  ('35b79fc0-51ab-5e5a-9959-7e13cbcf70b4', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'As used in the text, what does the word "constantly" most nearly mean?', '["Enough", "Nonstop", "Quickly", "Cautiously"]'::jsonb, 2, 'The following text is adapted from Willa Cather’s 1912 novel Alexander’s Bridge .

For the next few days Alexander was very busy. He took a desk in the office of a [Scottish] engineering firm on Henrietta Street, and was at work almost <u>constantly</u> . He avoided the clubs and usually dined alone at his hotel.'),
  ('9b317311-6b04-5830-8ccf-00128e1ac1a7', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text with the most logical and precise word or phrase?', '["originality", "publicity", "complexity", "practicality"]'::jsonb, 3, 'Though it does not guarantee a book’s commercial success, _____ can play a big role in that success—a well-executed marketing campaign helped to make Danielle Steel’s novel The Gift the fourth-best-selling novel of 1994.'),
  ('4d988a3b-5f48-5071-9b57-52a04794701d', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text with the most logical and precise word or phrase?', '["reduced", "evaluated", "determined", "acquired"]'::jsonb, 4, 'According to a team of neuroeconomists from the University of Zurich, ease of decision making may be linked to communication between two brain regions, the prefrontal cortex and the parietal cortex. Individuals tend to be more decisive if the information flow between the regions is intensified, whereas they make choices more slowly when information flow is _____.'),
  ('3e034b80-aa80-5854-b0bc-8570a8e72bd7', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text with the most logical and precise word or phrase?', '["precariousness", "exactitude", "resilience", "inconspicuousness"]'::jsonb, 5, 'Ecologist Exequiel Ezcurra and colleagues found that the inhabitants of the Mexica empire used natural landmarks to track time with a high degree of _____. By observing the sun’s position in relation to various points on the mountains surrounding the Basin of Mexico, the Mexica were able to precisely identify the dates when significant events such as solstices occurred.'),
  ('028915eb-60f5-5394-8e5e-9d4f01499099', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice best states the main purpose of the text?', '["To summarize Emerson’s biography.", "To explain why readers enjoy Emerson’s works.", "To describe a museum focused on Emerson’s life and works.", "To compare the Old Manse with other museums."]'::jsonb, 6, 'The Old Manse in Concord, Massachusetts, is the house where Ralph Waldo Emerson lived for a few years and wrote his essay “Nature.” Now the house is a museum dedicated to Emerson’s life and writings. Visitors travel to this museum to feel more connected to an author they admire. To encourage that sense of connection, the museum’s curators recommend nearby hiking trails and organize outdoor activities. Such activities help visitors appreciate the natural scenery that inspired Emerson.'),
  ('e9dc25f2-2f66-5b22-a420-25846bcddcc9', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice best states the function of the underlined sentence in the text as a whole?', '["It explains how 3D vision in horses and toads differs from the type of 3D vision discussed in the text.", "It offers a suggestion for future research on the aspect of 3D vision discussed in the text.", "It presents the results of the study of 3D vision discussed in the text.", "It explains why the animals discussed in the text were once thought to lack 3D vision."]'::jsonb, 7, 'Horses and toads can see in three dimensions (3D), which helps them perceive distance and depth. Octopuses and squid are thought to lack 3D vision. Many researchers once thought the same about cuttlefish, but Trevor Wardill and his team wanted to test whether this assumption was true. The team studied how cuttlefish wearing 3D glasses reacted to 3D images of shrimp (a favorite prey) projected on a tank wall. <u>Cuttlefish changed their striking position to match the 3D images, suggesting that their</u> <u>vision is more like that of horses and toads than that of octopuses or squid.</u>'),
  ('541c9006-2fc6-54a1-9514-4a8197066372', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice best describes the function of the references to “population density” and “individual physical fitness” in the text as a whole?', '["They represent factors that have been identified as important influences on walking decisions but that the text suggests are merely some of the many factors that may contribute to people’s decision-making about walking.", "They are examples of factors that studies suggest are important in people’s decision making about walking but that the text claims most people rarely consider when making walking decisions.", "They identify factors that Alfonzo argues have been overemphasized in studies of decision-making about walking but that the text asserts are relevant to most people’s walking decisions.", "They illustrate factors that researchers believe people consider when making walking decisions in most contexts but that the text argues are unique to walking decisions made by people in Boston."]'::jsonb, 8, 'Boston has high pedestrian traffic, but simply replicating a feature of Boston associated with walkability —e.g., its high number of intersections—may be insufficient to induce increased walking in other cities. As urbanist Mariela Alfonzo argues, our understanding of individuals’ decision-making about whether to walk is insufficiently robust: some studies emphasize the role of <u>population density</u>, others the role of <u>individual physical fitness</u>, and so on, but walking decisions are made in complex contexts in which multiple conditions and needs inform individuals’ choices.'),
  ('c53f2538-dbcc-5260-b471-4233e8effea4', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice best states the main idea of the text?', '["Poetry can forge connections between people from different cultures.", "Reading is a way of defying the modern world’s emphasis on money.", "Literature can metaphorically transport people to new places regardless of their means.", "People can learn more about distant places by reading books than by traveling to those places."]'::jsonb, 9, 'The following text is adapted from Emily Dickinson’s circa 1873 poem “There is no Frigate like a Book.” A frigate is a light, fast ship; coursers are swift horses.

There is no Frigate like a Book
To take us Lands away
Nor any Coursers like a Page
Of prancing Poetry—
This Traverse may the poorest take
Without oppress of Toll—
How frugal is the Chariot
That bears the Human soul.'),
  ('ac3230e1-1560-5be9-83a7-0389a2752ef4', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice best states the main idea of the text?', '["Several famous Indigenous writers increased their book sales when they began incorporating traditional stories.", "Recent Indigenous fiction writers are mixing traditional stories with popular literary genres.", "The success of Darcie Little Badger has influenced non Indigenous authors who write in popular literary genres.", "Non Indigenous authors should consider the expectations of Indigenous readers."]'::jsonb, 10, 'Darcie Little Badger is a novelist and a member of the Lipan Apache Tribe of Texas. Critics and fellow writers have praised her work for combining traditional Apache stories with popular genres of literature, such as fantasy and horror fiction. But Little Badger is not the only Indigenous writer to blend traditional stories with popular literature. In the 2016 novel Wrist, Nathan Adler successfully blended the oral storytelling tradition of their people, the Anishinaabe, with horror fiction.'),
  ('016411fc-a709-50f1-883b-405f7454f012', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which quotation from a translation of Uncle Vanya most effectively illustrates the claim?', '["Vanya says to Professor Serebrakoff, “We used to think of you as almost superhuman, but now the scales have fallen from my eyes and I see you as you are!”.", "Professor Serebrakoff says, “I am a book worm and a scholar, and am unfamiliar with practical affairs. I cannot. I find dispense with the help of well-informed people.”.", "Professor Serebrakoff says to Helena, “I am used to my library and the lecture hall and to the esteem and admiration of my colleagues. Now I suddenly find myself plunged into this wilderness [the estate], condemned to see the same stupid people from morning till night and listen to their futile conversations.”.", "Professor Serebrakoff says to Helena and Sonia, “No, no, no! Don’t leave me alone with [Vanya]! Oh, don’t He will begin to lecture me.”."]'::jsonb, 11, 'Uncle Vanya: Scenes from Country Life in Four Acts is an 1898 play by Anton Chekhov, originally written in Russian. In the play, Professor Serebrakoff and his wife Helena have come to stay at their country estate, which Vanya manages with the help of Sonia, the professor’s daughter from a previous marriage. Chekhov portrays the professor as being unable to adjust to living at the country estate, as is evident when ______'),
  ('1edb430c-59e3-59fe-a40d-0a39cd85f75c', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which quotation from a researcher would best support the student’s assertion?', '["“In one site in the wild where transgenic fish were observed, females outnumbered males, while in another the numbers of females and males were equivalent.”", "“Though some presence of transgenic fish in the wild has been recorded, there are insufficient studies of the impact of those fish on the ecosystems into which they are introduced.”", "“The ecosystems into which transgenic fish are known to have been introduced may represent a subset of the ecosystems into which the fish have actually been introduced.”", "“Through interbreeding, transgenic fish might introduce the trait of fluorescence into wild fish populations, making those populations more vulnerable to predators.”"]'::jsonb, 12, 'Fish whose DNA has been modified to include genetic material from other species are known as transgenic. Some transgenic fish have genes from jellyfish that result in fluorescence (that is, they glow in the dark). Although these fish were initially engineered for research purposes in the 1990s, they were sold as pets in the 2000s and can now be found in the wild in creeks in Brazil. A student in a biology seminar who is writing a paper on these fish asserts that their escape from Brazilian fish farms into the wild may have significant negative long-term ecological effects.'),
  ('a9ed511e-2e18-53ae-b363-575d9cc9e0e9', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice uses data from the table to most effectively complete the comparison?', '["was greater than the contribution made by professional services but equal to that made by arts/entertainment/recreation.", "exceeded the contribution made by both arts/entertainment/recreation and professional services.", "was lower than the contribution made by either arts/entertainment/recreation or professional services.", "surpassed the contribution made by arts/entertainment/recreation but fell short of that made by professional services."]'::jsonb, 13, '**Contributions of Three Key Industries to Oklahoma Economy in 2017**

| Industry | Approximate contribution |
| Professional services | \$7,694,000,000 |
| Arts/entertainment/recreation | \$1,296,300,000 |
| Tribal economic activity | \$7,312,400,000 |

The Cherokee Nation, the Quapaw Tribe, and the more than thirty other tribes in Oklahoma operate numerous businesses and collectively generate billions of dollars in revenue. In fact, when the tribes’ activity is regarded as a single industry, its contribution to the Oklahoma economy in 2017 _________'),
  ('44feab31-8144-5204-8697-326ada08845c', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice best describes data from the table that support Ehmann and colleagues’ hypothesis?', '["Individual 15 directed a higher proportion of peering events at immigrants to its home region than did individual 16, and individual 1 directed a higher proportion of peering events at immigrants to its home region than did individual 6.", "Individual 16 had the highest total number of peering events observed at 80.", "Individual 6 and individual 1 directed a lower proportion of peering events at immigrants to their home regions than did individual 15 and individual 16.", "The proportion of peering events directed at immigrants to immature orangutans’ home regions ranged from a low of 0.33 to a high of 1.00."]'::jsonb, 14, '**Peering at Adult Orangutans by Immature Orangutans**

| Individual | Site | Sex | Total number of peering events observed | Proportion of peering events directed at immigrants to immature individual’s home region |
| 16 | Suaq | male | 80 | 0.84 |
| 6 | Tuanan | female | 6 | 0.33 |
| 15 | Tuanan | male | 15 | 1.00 |
| 1 | Suaq | female | 17 | 0.41 |

One way that young orangutans acquire foraging skills is through a behavior scientists call peering—closely watching older orangutans as they engage in an activity that the young have not yet mastered. Since male orangutans typically leave the area of their birth upon maturity and females do not, Beatrice Ehmann and her colleagues hypothesized that it is more advantageous for immature males than females to devote attention to orangutans who are immigrants to the home region of the immature individual, and this should be reflected in sex-specific differences in peering behavior.'),
  ('ad117235-ea9b-5dd0-b625-5ac12f637919', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice most logically completes the text?', '["companies did not benefit from liberalization until at least three years after liberalization occurred.", "economists who held the standard view of liberalization failed to anticipate some serious negative effects of liberalization.", "companies in Thailand experienced a greater increase in investment following liberalization than did companies in Malaysia.", "empirical evidence was consistent with the scholarly consensus about the consequences of liberalization."]'::jsonb, 15, 'In May of 1987, Malaysia liberalized its stock market, meaning that it began allowing foreign individuals and businesses to invest money in Malaysian companies. This was part of a wave of stock market liberalizations around the world—Thailand in 1988, Mexico in 1989, and so on. The standard view among economists at the time was that liberalization would make it easier for companies to raise money from investors. Economist Peter Blair Henry examined the economies of 11 countries that were part of the liberalization wave and found that, on average, companies based in those countries received significant increases in investment in the three years following liberalization, suggesting that _____'),
  ('d535fe16-4517-5200-8c3e-45ff1613c856', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["create", "are creating", "have created", "creates"]'::jsonb, 16, '“He was just the man for such a place, and it was just the place for such a man.” This line is from Frederick Douglass’s autobiography Narrative of the Life of Frederick Douglass (1845). It’s an example of antimetabole, a writing technique that _____ emphasis by repeating a statement in a reversed order.'),
  ('f4397981-091b-5822-a00e-0db659331474', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["ate", "to eat", "still be eating", "eaten"]'::jsonb, 17, 'Over several years, anthropologist Livia Barbosa surveyed individuals in Brazil about their eating habits, collecting data, for example, on what days of the week respondents were more likely _____ common Brazilian foods, such as broa (a fennel-flavored cornbread) and tareco (a disk-shaped biscuit).'),
  ('d7358d8a-05df-52e4-a129-295dcf916ebe', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["struggle", "struggled", "were struggling", "had struggled"]'::jsonb, 18, 'To coders like Black Girls Code founder Kimberly Bryant, the computer programming languages Perl and Pascal have a clear difference: the former is an object-oriented language while the latter is not. Because both languages require highly technical knowledge to understand, though, laypeople _____ to distinguish between them.'),
  ('1191f238-1e54-5330-9ae3-0effe0c3571b', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["painter, Gani Odutokun,", "painter Gani Odutokun.", "painter Gani Odutokun", "painter, Gani Odutokun"]'::jsonb, 19, 'Included among a particular group of mid-twentieth-century artists known as the Zaria School, Nigerian expressionist _____ was known for using bold lines and for drawing on Indigenous artistic traditions and rejecting Western values.'),
  ('0177f1f1-4acc-5213-a075-99ebdb34b8e7', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["efforts, however;", "efforts however", "efforts: however,", "efforts, however,"]'::jsonb, 20, 'The Timeline of African American Music, a website that traces the history of genres such as soul and ragtime, is the result of decades of research by ethnomusicologist Portia K. Maultsby. She was not alone in her _____ Fernando Orejuela and Stephanie Shonekan, among other scholars, also contributed to the project.'),
  ('a13241af-6698-5240-a307-6f0ee95f683c', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text with the most logical transition?', '["meanwhile,", "similarly,", "hence,", "subsequently,"]'::jsonb, 21, 'In a 2022 analysis, researchers applied a statistical model to a set of words to infer the rate of cognate replacementthe rate at which a word will be replaced over time with a noncognate formin Indo-European languages. The researchers found that negative adjectives like grim evolve most rapidly; ______ negative nouns evolve most slowly.'),
  ('258b0af8-c046-5bc3-8b43-7cad2410a0cd', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text with the most logical transition?', '["Soon,", "Regardless,", "However,", "Specifically,"]'::jsonb, 22, 'In the 1880s, inventor Lewis Latimer improved upon Thomas Edison’s design for the electric light bulb. _____ Latimer made the light bulb more durable by placing cardboard around its carbon filament. With this innovation, Latimer became the first Black inventor to contribute to the electrification of the world.'),
  ('e4e265fe-c5ad-511b-8766-6183fe48d30d', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice completes the text with the most logical transition?', '["Consequently,", "By contrast,", "What’s more,", "Nevertheless,"]'::jsonb, 23, 'Soil polluted with nickel (a heavy metal) is harmful to many plants and animals, but the plant species Najas marina, or spiny water nymph, can thrive in such conditions. _____ as a metal hyperaccumulator, Najas marina absorbs a large amount of nickel and sequesters it in its roots and shoots, thereby reducing concentrations of this harmful substance in the soil.'),
  ('48bb7102-2f1e-5f7b-ab24-796d73befbb5', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'Which choice most effectively uses information from the given sentences to emphasize the size of the sculpture?', '["Richard Serra is an American artist known for his large metal sculptures.", "Richard Serra’s Rotate is made of weathering steel.", "American artist Richard Serra creates large sculptures from metals such as weathering steel.", "Rotate a large metal sculpture by artist Richard Serra stretches roughly 6 feet wide and 12 feet tall."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

Richard Serra is an American artist.
He is known for his large metal sculptures.
His sculpture Rotate is roughly 6 feet wide and 12 feet tall.
It is made from weathering steel.'),
  ('d12b59ee-7acc-5c40-900d-894fd8707223', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'The student wants to emphasize a difference between the two approaches to dyeing blue jeans. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Though created using a different process, Rai’s dye contains the same ingredient as the dye produced by blue jean manufacturers.", "Nanocellulose is a natural, plant-based substance that separates the molecules of indigo powder, which doesn’t dissolve in water.", "The traditional approach to dyeing blue jeans is to dip them in a solution containing hazardous chemicals.", "Rai’s approach substitutes a natural plant-based substance for the hazardous chemicals that manufacturers have traditionally used."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Traditionally, manufacturers have dyed denim jeans blue by dipping them in a solution containing indigo powder.
Indigo doesn’t dissolve in just water, so manufacturers must mix hazardous chemicals with water to dissolve the powder.
Textile researcher Smriti Rai discovered a process for dyeing blue jeans without chemicals. Rai added indigo powder to a hydrogel containing nanocellulose and produced a dye that could be spread directly onto the denim.
Nanocellulose is a natural, plant-based substance that separates the molecules of indigo powder.'),
  ('aaee9c20-a7fe-5373-94fb-e20263d6d9e0', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'The student wants to emphasize a similarity between P waves and S waves. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["P waves and S waves both travel beneath Earth’s surface, causing the ground to move.", "P waves travel away from an earthquake’s starting point at a higher rate of speed than do S waves.", "Spreading out from the focus of an earthquake, P waves move the ground backward and forward.", "Although P waves and S waves start at the same point, they behave very differently."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Earthquakes start at a point called a “focus” and spread out from there as seismic waves. The two types of seismic waves that travel beneath Earth’s surface are primary waves (P waves) and secondary waves (S waves).
P waves travel more quickly beneath Earth’s surface than do S waves.
P waves compress and expand the ground, causing it to move backward and forward. S waves cause the ground to move from side to side.'),
  ('c6c6d48f-e0e1-50c0-843f-1aec3566beec', '1ae03748-f6c5-5811-9d1d-58c02fe369e3', 'The student wants to specify how long the Gambia officially used the Gambian pound. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Gambian pound was the Gambia’s official currency from 1965 to 1971.", "Though the Gambia currently uses the dalasi, the country’s former official currency was introduced in 1965.", "The dalasi has been the Gambia’s official currency since 1971, when it replaced the Gambian pound.", "Countries sometimes adopt new currency systems, as the Gambia did when it replaced the Gambian pound with the dalasi."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

A currency is a money system.
Sometimes, countries adopt a new currency to replace an older one.
The Gambia adopted the Gambian pound as its official currency in 1965.
The dalasi replaced the Gambian pound in 1971.
The dalasi remains the Gambias official currency.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('8267c2bc-4fd2-5bb2-8ed2-d4fe34305047', 3, null, '**Choice D is correct.** The sentence explains why Burns received the fellowship—"because of his lifetime contributions to the arts"—so the blank must indicate that he was the recipient: "chosen to receive it." "Chosen" precisely matches the causal explanation provided.
**Choice A is incorrect.** "Confused" does not fit the cause-and-effect structure; being confused is unrelated to having lifetime contributions that justify receiving an award.
**Choice B is incorrect.** "Reluctant" means unwilling or hesitant. That meaning contradicts the explanatory clause: his lifetime contributions are given as the reason he received the fellowship, not a reason he resisted it.
**Choice C is incorrect.** "Ineligible" means not qualifying; that directly conflicts with the statement that he received the fellowship because of his lifetime contributions.
**Faster approach:** For Words in Context items, read the clause after the blank first to identify whether it gives a reason, result, contrast, or description; then choose the word that matches that relationship (here, a result of being chosen).'),
  ('35b79fc0-51ab-5e5a-9959-7e13cbcf70b4', 1, null, '**Choice B is correct.** In the passage, Alexander "was very busy" and "at work almost constantly," which indicates he was working continually or without stopping; "nonstop" best matches that sense.
**Choice A is incorrect.** "Enough" refers to sufficiency and does not convey continuous or repeated action, so it doesn’t match the context of being busy and always at work.
**Choice C is incorrect.** "Quickly" suggests speed, but the sentence emphasizes duration and frequency of work rather than how fast he worked.
**Choice D is incorrect.** "Cautiously" describes manner (carefulness), which is unrelated to the idea of working continually; the passage focuses on how often he worked, not how he worked.
**Faster approach:** Use the surrounding context (phrases like "very busy" and "avoided the clubs") to identify whether the word refers to frequency, manner, speed, or sufficiency, then choose the synonym that matches that category.'),
  ('9b317311-6b04-5830-8ccf-00128e1ac1a7', 1, null, '**Choice B is correct.** The sentence contrasts something that does not guarantee commercial success with a factor that nonetheless "can play a big role in that success," and the example that follows — "a well-executed marketing campaign" — directly supports the idea of generating attention; "publicity" precisely names that factor. The wording is both logical and specific to the example given.
**Choice A is incorrect.** "Originality" refers to the novelty of the book’s content, which is not what the example (a marketing campaign) is illustrating.
**Choice C is incorrect.** "Complexity" describes the nature of the book’s content and is unrelated to being promoted by a marketing campaign.
**Choice D is incorrect.** "Practicality" concerns usefulness or applicability and does not match the example of publicity generated by marketing.
**Faster approach:** Use the example clause (marketing campaign) as a clue: pick the choice that names what a campaign produces (publicity) and eliminate content-descriptive options.'),
  ('4d988a3b-5f48-5071-9b57-52a04794701d', 0, null, '**Choice A is correct.** The sentence contrasts heightened information flow, which makes individuals more decisive, with the opposite condition that would slow decision making. ‘‘Reduced’’ directly expresses a decrease in flow and fits grammatically and logically: when information flow is reduced, choices are made more slowly.
**Choice B is incorrect.** ‘‘Evaluated’’ means judged or assessed, which does not express a change in amount or intensity of information flow and therefore fails to create the intended contrast.
**Choice C is incorrect.** ‘‘Determined’’ means established or decided and does not describe the quantity or intensity of communication between brain regions.
**Choice D is incorrect.** ‘‘Acquired’’ means gained or obtained; it does not convey a decrease in information flow and so is not the logical opposite of ‘‘intensified.’b>
**Faster approach:** For contrast-based sentence completions, identify the meaning of the given clause (here, ‘‘intensified’’ = increased) and pick the choice that is the clear opposite (a synonym of ‘‘decreased’’).'),
  ('3e034b80-aa80-5854-b0bc-8570a8e72bd7', 1, null, '**Choice B is correct.** The sentence describes using natural landmarks and the sun’s position to "precisely identify the dates" of events such as solstices; "exactitude" directly means precision and accuracy, matching both the context and the adverb "precisely."
**Choice A is incorrect.** "Precariousness" means instability or risk, which contradicts the idea of reliably identifying dates.
**Choice C is incorrect.** "Resilience" refers to ability to recover from difficulties; it does not relate to precision in timekeeping.
**Choice D is incorrect.** "Inconspicuousness" means not easily seen—this conflicts with using visible landmarks to track the sun and would not support precise date identification.
**Faster approach:** Look for a word that aligns with "precisely identify"—choose the synonym for precision (exactitude) and eliminate meanings that imply instability, recovery, or invisibility.'),
  ('028915eb-60f5-5394-8e5e-9d4f01499099', 2, null, '**Choice C is correct.** The passage focuses on the Old Manse as a museum dedicated to Emerson’s life and writings, describing what visitors experience (feeling connected to Emerson) and what the curators do (recommend trails and organize outdoor activities). Those details all serve to describe the museum and its purpose.
**Choice A is incorrect.** The passage gives only a brief fact that Emerson lived there and wrote “Nature,” not a summary of his biography.
**Choice B is incorrect.** The passage suggests why visitors feel connected at the museum, but it does not attempt to explain broadly why readers enjoy Emerson’s works.
**Choice D is incorrect.** There is no comparison between the Old Manse and any other museums in the passage.
**Faster approach:** Identify the subject (Old Manse/museum) and the author’s intent (what the passage does with that subject—describe it); eliminate choices that introduce topics or actions not supported by the text.'),
  ('e9dc25f2-2f66-5b22-a420-25846bcddcc9', 2, null, '**Choice C is correct.** The underlined sentence reports what happened in the researchers'' experiment —cuttlefish changed their striking position to match 3D images — and draws the resulting conclusion that their vision resembles horses'' and toads'' 3D vision. This is a clear presentation of the study’s results and their interpretation.
**Choice A is incorrect.** The sentence does not explain differences between horses'' and toads'' 3D vision and any other form of 3D vision; it simply says cuttlefish vision is more like horses'' and toads''.
**Choice B is incorrect.** The sentence does not propose future research; it summarizes experimental observations and an interpretation, not a suggestion for further study.
**Choice D is incorrect.** The sentence does not explain why researchers once thought the animals lacked 3D vision; earlier text states that belief, but the underlined sentence gives experimental results, not an explanation of past assumptions.
**Faster approach:** Look for verbs that report findings (e.g., "changed," "suggesting") to identify sentences that state results; eliminate choices about explanation or future research.'),
  ('541c9006-2fc6-54a1-9514-4a8197066372', 0, null, '**Choice A is correct.** The passage lists “population density” and “individual physical fitness” as examples of factors that some studies emphasize, then immediately states that walking decisions occur in "complex contexts in which multiple conditions and needs" inform choices; this language shows those factors are among many influences rather than complete explanations.
**Choice B is incorrect.** The passage does not claim people rarely consider those factors; it says studies emphasize them but that decision-making is complex, not that individuals ignore them.
**Choice C is incorrect.** The passage does not argue these factors were overemphasized while still asserting they are relevant to most people’s decisions; it simply presents them as some contributing factors within complex contexts.
**Choice D is incorrect.** The passage does not say these factors are unique to Boston or that researchers view them as relevant in most contexts only for Boston; it discusses studies generally and the broader complexity of walking decisions.
**Faster approach:** Spot the contrast words (e.g., "some," "others," "complex") and eliminate choices that overstate or localize the role of the examples—choose the answer that treats them as merely some of many factors.'),
  ('c53f2538-dbcc-5260-b471-4233e8effea4', 2, null, '**Choice C is correct.** The poem uses extended metaphorical language—calling a book a "Frigate" and a page a "Courser"—to show that "a Book" and "a Page" can take readers to other "Lands". The line "This Traverse may the poorest take / Without oppress of Toll" makes explicit that literature can transport people "regardless of their means." Together these lines state the main idea that literature can metaphorically transport people whether or not they have money.
**Choice A is incorrect.** The poem focuses on the transporting power of books, not on forming cross-cultural connections; it does not mention people from different cultures.
**Choice B is incorrect.** While the poem notes that the poorest can travel without a toll, it does not argue broadly about "defying the modern world’s emphasis on money."
**Choice D is incorrect.** The poem claims books can transport readers, but it does not claim reading is superior to actual travel or that one learns more from books than from traveling.
**Faster approach:** Identify the central metaphor (book = ship) and the concluding qualifying line about the poorest taking the journey; those two elements together give the main idea for this question type.'),
  ('ac3230e1-1560-5be9-83a7-0389a2752ef4', 1, null, '**Choice B is correct.** The passage describes Darcie Little Badger and Nathan Adler as Indigenous writers who combine traditional Indigenous stories or oral storytelling with popular genres (fantasy, horror), so the main idea is that recent Indigenous fiction writers are mixing traditional stories with popular literary genres.
**Choice A is incorrect.** The passage does not say anything about increased book sales; it discusses blending storytelling traditions with genres, not commercial success.
**Choice C is incorrect.** The passage mentions Darcie Little Badger and another Indigenous writer, not that her success influenced non-Indigenous authors; both examples are Indigenous writers.
**Choice D is incorrect.** The passage does not make a recommendation for non-Indigenous authors or discuss reader expectations; it simply describes a literary trend among Indigenous writers.
**Faster approach:** Look for the general statement that summarizes all examples—identify what both named writers have in common (mixing traditional stories with popular genres) and choose the answer that restates that idea.'),
  ('016411fc-a709-50f1-883b-405f7454f012', 2, null, '**Choice C is correct.** The claim is that the professor cannot adjust to living at the country estate; choice C explicitly contrasts the professor’s accustomed life — “library and the lecture hall” and “esteem and admiration” — with his present condition of being “plunged into this wilderness,” where he is “condemned” to see “stupid people” and their “futile conversations,” directly showing his inability to adapt.
**Choice A is incorrect.** That quote records Vanya’s changed opinion of the professor, not the professor’s own difficulty adjusting to the estate.
**Choice B is incorrect.** Although it suggests the professor is unfamiliar with practical affairs, the garbled phrasing and lack of explicit reference to discomfort at the estate make it a weaker and less direct illustration than C.
**Choice D is incorrect.** This line shows anxiety about being left with Vanya and a fear of being lectured, but it does not directly state the professor’s inability to adjust to life at the country estate.
**Faster approach:** Scan choices for a direct contrast between the professor’s former urban/intellectual life and his present country surroundings; the option that explicitly uses that contrast is correct.'),
  ('1edb430c-59e3-59fe-a40d-0a39cd85f75c', 3, null, '**Choice D is correct.** The student’s claim is that escaped transgenic fish "may have significant negative long-term ecological effects," and Choice D offers a clear mechanism by which harm could occur: interbreeding could spread fluorescence into wild populations and increase predation vulnerability, which would produce the negative ecological effects the student asserts.
**Choice A is incorrect.** It reports only population counts in two sites and does not indicate any negative long-term ecological effects.
**Choice B is incorrect.** It emphasizes insufficient study and uncertainty rather than providing evidence that the fish cause harmful long-term effects.
**Choice C is incorrect.** It suggests underreporting of introductions but does not describe specific harmful ecological consequences.
**Faster approach:** For evidence questions, immediately eliminate choices that state uncertainty or mere occurrence; pick the quotation that directly describes a specific harmful effect supporting the claim.'),
  ('a9ed511e-2e18-53ae-b363-575d9cc9e0e9', 3, null, '**Choice D is correct.** The table shows tribal economic activity at \$7,312,400,000, professional services at \$7,694,000,000, and arts/entertainment/recreation at $1,296,300,000.Since$7,312,400,000 is greater than \$1,296,300,000 but less than \$7,694,000,000, tribal activity "surpassed the contribution made by arts/entertainment/recreation but fell short of that made by professional services."
**Choice A is incorrect.** Tribal activity is not equal to arts/entertainment/recreation (the two amounts differ substantially), so the statement is false.
**Choice B is incorrect.** Tribal activity does not exceed professional services; \$7,312,400,000 is less than \$7,694,000,000.
**Choice C is incorrect.** Tribal activity is not lower than both others; it is higher than
arts/entertainment/recreation.
**Faster approach:** Compare the billions-place digits first (both tribal and professional begin with 7 billion, arts with 1 billion) to see which are clearly larger, then compare the remaining digits to decide between two close billion values.'),
  ('44feab31-8144-5204-8697-326ada08845c', 2, null, '**Choice C is correct.** The table shows the two males (individuals 15 and 16) directed proportions of peering events at immigrants of 1.00 and 0.84, respectively, while the two females (individuals 1 and 6) directed proportions of 0.41 and 0.33. Thus individuals 6 and 1 (females) directed lower proportions at immigrants than did individuals 15 and 16 (males), which supports the hypothesis that immature males focus more on immigrants than immature females do.
**Choice A is incorrect.** Although the numerical comparisons are true (15: 1.00 > 16: 0.84; 1: 0.41 > 6: 0.33), this statement compares within sexes rather than describing the sex-specific pattern that supports the hypothesis.
**Choice B is incorrect.** Individual 16 did have 80 total peering events, but this fact alone does not address the hypothesis about sex differences in the proportion of peering directed at immigrants.
**Choice D is incorrect.** The range stated (0.33 to 1.00) is correct numerically but simply restates the spread of proportions and does not explicitly relate the data to the sex-specific pattern the hypothesis predicts.
**Faster approach:** Scan the table for the sex column and compare proportions by sex—directly comparing male versus female proportions quickly shows whether the data support the hypothesis.'),
  ('ad117235-ea9b-5dd0-b625-5ac12f637919', 3, null, '**Choice D is correct.** The passage says that Henry found that, on average, companies received significant increases in investment in the three years following liberalization; that empirical finding directly supports the economists'' standard view that liberalization makes it easier for companies to raise money. Thus the evidence is consistent with the scholarly consensus about liberalization’s consequences.
**Choice A is incorrect.** The sentence reports increases in the three years following liberalization; it does not claim companies "did not benefit until at least three years" after—A misreads the timing.
**Choice B is incorrect.** The finding of increased investment does not indicate that economists failed to anticipate negative effects; it supports a positive expected effect instead.
**Choice C is incorrect.** The study averaged results across 11 countries; nothing in the sentence compares Thailand and Malaysia, so C is unsupported.
**Faster approach:** Look for whether the evidence supports or contradicts the earlier claim—inference questions with "suggesting that" usually require choosing the answer that restates the claim the evidence supports.'),
  ('d535fe16-4517-5200-8c3e-45ff1613c856', 3, null, '**Choice D is correct.** The noun phrase "a writing technique" is singular, so the verb in the relative clause must be third-person singular present. "Creates" agrees in number and fits the general descriptive sense: antimetabole is a device that creates emphasis by reversing word order.
**Choice A is incorrect.** "Create" is plural and does not agree with the singular subject "a writing technique."
**Choice B is incorrect.** "Are creating" is plural and progressive, which conflicts with the singular subject and changes the simple, general descriptive tense required here.
**Choice C is incorrect.** "Have created" is present perfect and plural (or requires a singular "has"), and it implies a completed action rather than a general characteristic of the technique.
**Faster approach:** Use subject-verb agreement: identify the singular subject "a writing technique" and choose the third-person singular present-form verb "creates."'),
  ('f4397981-091b-5822-a00e-0db659331474', 1, null, '**Choice B is correct.** The phrase "more likely" is followed by the infinitive form "to" + verb, so "more likely to eat" is the grammatically correct construction. The sentence then reads naturally: "... respondents were more likely to eat common Brazilian foods..." which conforms to Standard English.
**Choice A is incorrect.** "Ate" is the simple past tense; it does not pair correctly with the comparative phrase "more likely" without an auxiliary (e.g., "more likely ate" is ungrammatical here).
**Choice C is incorrect.** "Still be eating" is a progressive form that implies an ongoing action and requires a different context (and auxiliary), so it does not fit after "more likely."
**Choice D is incorrect.** "Eaten" is a past participle and would require an auxiliary verb (e.g., "have eaten") to be grammatical; standing alone after "more likely" it is incorrect.
**Faster approach:** Recognize that "more likely" is commonly followed by the infinitive "to" + verb; immediately eliminate non-infinitive forms and choose the infinitive.'),
  ('d7358d8a-05df-52e4-a129-295dcf916ebe', 0, null, '**Choice A is correct.** The sentence uses present-tense verbs earlier ("have," "require"), so the clause describing what laypeople do should also be in the simple present. "Laypeople struggle to distinguish between them" correctly matches the present tense and conveys a general truth.
**Choice B is incorrect.** "Struggled" is past tense and would create a tense mismatch with the present-tense verbs "have" and "require."
**Choice C is incorrect.** "Were struggling" is past progressive and likewise conflicts with the sentence’s present-tense framing, implying an ongoing past action rather than a general present difficulty.
**Choice D is incorrect.** "Had struggled" is past perfect and indicates an action completed before another past event; that meaning does not fit the present-tense context of the sentence.
**Faster approach:** Match verb tense to nearby verbs—choose the present tense when surrounding verbs are present to express a general or ongoing truth.'),
  ('1191f238-1e54-5330-9ae3-0effe0c3571b', 2, null, '**Choice C is correct.** The phrase identifies a single person by title and name — "Nigerian expressionist painter Gani Odutokun" — so no commas should separate the title from the name. The name is an essential (restrictive) modifier that specifies which artist is meant, so the sentence requires no internal commas and must end with the sentence-final period that is already present: "...Nigerian expressionist painter Gani Odutokun was known..."
**Choice A is incorrect.** The commas set off the name as a nonrestrictive appositive, which would imply the name is extra information rather than essential identification; additionally, it leaves a trailing comma before the sentence continues, creating incorrect punctuation.
**Choice B is incorrect.** Although it places a period at the end, it omits the necessary period for the full sentence when combined with the passage punctuation; more importantly, a comma between "painter" and the name is not needed because the name is essential.
**Choice D is incorrect.** This choice inserts a comma before the name but omits the final period; like A, it incorrectly treats the name as nonrestrictive and mispunctuates the sentence.
**Faster approach:** When a title immediately followed by a name identifies who is being talked about (an essential appositive), do not use commas; choose the option with no internal commas and with correct sentence-ending punctuation.'),
  ('0177f1f1-4acc-5213-a075-99ebdb34b8e7', 0, null, '**Choice A is correct.** The sentence requires a pair of commas to set off the interrupter "however" and also needs a semicolon after the interrupter to connect two independent clauses ("She was not alone in her efforts" and "Fernando Orejuela and Stephanie Shonekan... also contributed to the project"). Choice A provides "efforts, however;" which correctly places a comma before the interrupter and a semicolon after it, yielding: "She was not alone in her efforts, however; Fernando Orejuela..." This punctuation conforms to standard conventions for linking two related independent clauses with a conjunctive adverb.
**Choice B is incorrect.** "efforts however" omits necessary punctuation: there is no comma before the interrupter and no semicolon (or comma and coordinating conjunction) to join the two independent clauses, resulting in a run-on or comma splice error.
**Choice C is incorrect.** "efforts: however," uses a colon before "however" and a comma after it; a colon is used to introduce a list or an explanation and is not appropriate for setting off an interrupting conjunctive adverb between two independent clauses.
**Choice D is incorrect.** "efforts, however," places commas around the interrupter but leaves the two independent clauses separated only by a comma, which creates a comma splice; a stronger break (semicolon) is required after "however" to join the clauses correctly.
**Faster approach:** Recognize that "however" here is a conjunctive adverb linking two independent clauses; quickly check punctuation before and after it. You should have a comma before the interrupter and a semicolon (or period) after it—so choose the answer with "..., however;".'),
  ('a13241af-6698-5240-a307-6f0ee95f683c', 0, null, '**Choice A is correct.** The sentence sets up a contrast between the evolution rate of negative adjectives ("most rapidly") and negative nouns ("most slowly"). "Meanwhile" signals a simultaneous or contrasting situation and fits smoothly: "negative adjectives like grim evolve most rapidly; meanwhile, negative nouns evolve most slowly." It maintains the parallel structure and conveys the intended contrast.
**Choice B is incorrect.** "Similarly" would indicate that negative nouns behave in the same way as negative adjectives, which contradicts the second clause that says they evolve "most slowly."
**Choice C is incorrect.** "Hence" implies a causal relationship (that one fact follows from the other), but the sentence is contrasting two observed rates rather than stating that one causes the other.
**Choice D is incorrect.** "Subsequently" indicates a temporal sequence (one event happening after another), but the sentence describes two comparative rates rather than a sequence in time.
**Faster approach:** Look for the logical relation signaled by key words (e.g., "most rapidly" vs "most slowly"); choose a transition that matches that relation (contrast/comparison vs cause vs time).'),
  ('258b0af8-c046-5bc3-8b43-7cad2410a0cd', 3, null, '**Choice D is correct.** The second sentence gives a specific example of how Latimer improved Edison’s design (placing cardboard around the carbon filament), so the transition "Specifically," correctly signals that the sentence will provide a concrete detail that elaborates on the general statement in the first sentence.
**Choice A is incorrect.** "Soon," indicates a temporal relationship, but the second sentence does not emphasize timing; it provides a specific description of the improvement, not when it happened.
**Choice B is incorrect.** "Regardless," signals concession or dismissal of a prior point; nothing in the context suggests a contrast or that the upcoming detail disregards the first sentence.
**Choice C is incorrect.** "However," signals a contrast or contradiction with the previous sentence, but the second sentence supports and specifies the first sentence rather than contradicting it.
**Faster approach:** Identify whether the next sentence adds a specific detail, shows contrast, or indicates time; match that function to the transition (e.g., use "Specifically" for a direct elaboration).'),
  ('e4e265fe-c5ad-511b-8766-6183fe48d30d', 2, null, '**Choice C is correct.** The sentence after the blank explains how Najas marina reduces nickel in soil, which adds information about the plant’s beneficial role. "What’s more," signals that the following clause provides an additional, reinforcing detail about the plant’s capabilities, so it logically connects the two sentences.
**Choice A is incorrect.** "Consequently," indicates a result or outcome; it would imply that the plant’s thriving is caused by the following clause, but the clause actually explains an additional beneficial trait, not a direct consequence.
**Choice B is incorrect.** "By contrast," signals a difference or opposition, but the next clause does not present a contrast—it gives further information about how the plant mitigates nickel pollution.
**Choice D is incorrect.** "Nevertheless," indicates concession; the prior clause already contains a contrast with "but," so "nevertheless" would be redundant and would incorrectly suggest a counterpoint rather than added information.
**Faster approach:** Identify whether the second clause adds information, shows contrast, or gives a result; then choose the transition that matches that relationship (here, an addition—"What’s more").'),
  ('48bb7102-2f1e-5f7b-ab24-796d73befbb5', 3, null, '**Choice D is correct.** It directly emphasizes the sculpture’s size by naming the work and giving its dimensions: “roughly 6 feet wide and 12 feet tall,” which uses the specific numeric details from the notes to highlight scale.
**Choice A is incorrect.** Although it mentions that Serra is known for large metal sculptures, it does not use the specific dimensions that most strongly emphasize the sculpture’s size.
**Choice B is incorrect.** This choice only states the material (weathering steel) and says nothing about size.
**Choice C is incorrect.** It generalizes about Serra’s work and materials but does not provide the specific dimensions that emphasize how large this sculpture is.
**Faster approach:** Look for the choice that repeats the exact size details (numbers and units); the option with the explicit dimensions will always best emphasize size.'),
  ('d12b59ee-7acc-5c40-900d-894fd8707223', 3, null, '**Choice D is correct.** It directly contrasts the two methods by stating that Rai’s approach replaces the hazardous chemicals manufacturers traditionally use with a natural, plant-based substance (nanocellulose), which matches the notes describing conventional chemical dissolution and Rai’s hydrogel method.
**Choice A is incorrect.** It emphasizes similarity (same ingredient) rather than the requested difference between the approaches.
**Choice B is incorrect.** Though factually true, it merely restates that nanocellulose separates indigo molecules and that indigo doesn’t dissolve in water; it doesn’t emphasize the contrast between the two methods.
**Choice C is incorrect.** It accurately describes the traditional method but does not highlight how Rai’s approach differs from it.
**Faster approach:** Look for the answer that explicitly contrasts the two methods (words like "substitutes," "replaces," or "instead of"); eliminating answers that only restate facts or note similarities quickly yields the correct choice.'),
  ('aaee9c20-a7fe-5373-94fb-e20263d6d9e0', 0, null, '**Choice A is correct.** The notes state that both P waves and S waves “travel beneath Earth’s surface” and that each type causes the ground to move (P waves compress and expand the ground; S waves move it side to side), so this choice accurately emphasizes a clear similarity using information from the notes.
**Choice B is incorrect.** This sentence emphasizes a difference in speed (P waves travel more quickly), not a similarity between the two wave types.
**Choice C is incorrect.** This sentence describes only P waves (their motion and origin) and does not compare P waves and S waves or emphasize a similarity.
**Choice D is incorrect.** This sentence highlights how the waves “behave very differently,” which stresses differences rather than emphasizing a similarity.
**Faster approach:** Scan the notes for language that both wave types share (words like “both” or identical properties listed for each) and choose the answer that repeats that shared trait.'),
  ('c6c6d48f-e0e1-50c0-843f-1aec3566beec', 0, null, '**Choice A is correct.** The notes state that the Gambian pound was adopted in 1965 and was replaced by the dalasi in 1971, so saying it was the Gambia’s official currency from 1965 to 1971 directly and precisely specifies how long it was used.
**Choice B is incorrect.** Although it mentions the 1965 introduction, it does not state when the Gambian pound ceased to be the official currency and therefore fails to specify the duration.
**Choice C is incorrect.** This choice indicates when the dalasi became official (1971) but does not state when the Gambian pound began, so it does not specify the full period the pound was used.
**Choice D is incorrect.** This is a general statement about countries adopting new currencies and does not provide the specific years the Gambian pound was in use.
**Faster approach:** Look for the explicit adoption and replacement years in the notes and express the period as "from YEAR to YEAR."')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Dec 2023 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('530c2438-5ab3-533a-a685-62a1b68437b5', 'PeaklyTest Dec 2023 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Dec 2023 PeaklyTest · 27 questions · 32 minutes', 32, 251, true, 'PeaklyTest Dec 2023 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('84afe7fa-c028-5235-9418-c8fb1f268346', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text with the most logical and precise word or phrase?', '["examples of", "concerns about", "indications of", "similarities with"]'::jsonb, 1, 'Though not closely related, the hedgehog tenrecs of Madagascar share basic _____ true hedgehogs, including protective spines, pointed snouts, and small body size—traits the two groups of mammals independently developed in response to equivalent roles in their respective habitats.'),
  ('e17644d2-af23-5771-aa82-9156464bb27a', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text with the most logical and precise word or phrase?', '["deserving", "conspicuous", "uncertain", "enduring"]'::jsonb, 2, 'Nancy Bird-Walton, who was an aviation pioneer, undoubtedly accomplished much, but her place in our historical memory is perhaps more _____ than that of a noteworthy “first” such as Krystyna Chojnowska-Liskiewicz, who was the first woman to sail solo around the world, a deed for which she will always be remembered.'),
  ('140d5860-b285-57bd-9133-dd8936776207', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text with the most logical and precise word or phrase?', '["mitigate", "constrict", "repudiate", "buttress"]'::jsonb, 3, 'Some robots such as WABOT-2 (developed in 1984) and Sophia (developed in 2015) are designed to resemble humans so that people will find it easier to interact with them. To that end, certain features such as bipedal locomotion can help to _____ people’s feelings of comfort, but a robot that looks too human can fall into the “uncanny valley,” meaning that its appearance unintentionally unsettles those who encounter it.'),
  ('193a8118-31a7-54ea-bf52-35edec818217', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text with the most logical and precise word or phrase?', '["controversial among", "antagonistic toward", "imitated by", "inconsequential to"]'::jsonb, 4, 'While recent scholarship has undermined claims that the works of twelfth-century Islamic philosopher Ibn Rushd were _____ other Muslim philosophers of his time, it is indisputable that his location in the Muslim-ruled area of what is now Spain meant that his works were primarily available thousands of miles west of the era’s center of Islamic thought.'),
  ('b9f786e9-e2d9-5f91-9ff8-b84372069eee', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice best describes the overall structure of the text?', '["It introduces the topic of a scientific study, describes the study’s importance, and then presents the study’s results.", "It identifies a particular approach to research, lists some benefits of that approach, and then mentions a study in which that approach was used.", "It describes the development of a type of scientific collaboration, shows how that type of collaboration has been used in a particular field of study, and then suggests future collaborative projects.", "It argues for a new approach to scientific research, comments on the public’s opinion about the approach, and then describes how that approach was applied in a certain study."]'::jsonb, 5, 'Community science, which involves professional scientists collaborating with amateur science enthusiasts to study a topic, is often an effective and engaging way to conduct research. It can lead to greater public awareness of an ecosystem, provide youth with learning experiences outside of the classroom, and increase the amount of data researchers can collect. This approach was essential to the success of a study by biologist Grace Herzel and colleagues of butterfly wing patterns and their relation to behavior, which included findings from hundreds of students and community members in northwestern Arkansas.'),
  ('381acc39-fc64-522f-82b5-7d81eca07112', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Based on the texts, the author of Text 1 and the author of Text 2 would most likely give the same answer to which question?', '["Are the barriers used in Xiao and colleagues study sufficient to ensure that nutrient transfer could only occur via a CMN?", "Did Wahbi and colleagues study effectively exclude any nutrient pathway other than a CMN?", "Do plants that transfer nutrients through a root-to-root pathway also transmit nutrients via a CMN?", "Is there an available barrier material that can block roots and liquids while allowing fungal strands through?"]'::jsonb, 6, '**Text 1**

In separate studies, Yanbo Xiao and colleagues and Sana Wahbi and colleagues examined whether plants transfer nutrients to one another using a common mycorrhizal network (CMN) a lattice of fungal strands in the soil. Xiao and colleagues excluded all pathways other than the CMN by using barriers to keep the plants root systems separate while allowing mycorrhizal strands through a crucial step Wahbi and colleagues study did not take.

**Text 2**

Xiao and colleagues took the necessary precaution of separating the plants root systems (thereby excluding root-to-root transmission). However, any barrier used must allow the threadlike hyphae of a CMN to pass through, and this permeability would also allow liquids through. Thus, the researchers experimental design cannot ensure that any nutrient transfer observed can be attributed to a CMN and not to some other pathway.'),
  ('d0ad022a-e02e-5a8a-ac57-da9b9f1cb412', '530c2438-5ab3-533a-a685-62a1b68437b5', 'According to the text, what is one potential drawback of Hidalgo and colleagues'' method?', '["It may lead to conclusions that are not reflective of all the amenities in a given neighborhood.", "It is likely to contribute to inaccurate identifications of the boundaries of specific neighborhoods.", "It is based on recent advancements from other fields that have yet to be applied outside of those contexts.", "It depends upon data that are likely to be outdated."]'::jsonb, 7, 'Researchers Cesar A. Hidalgo, Elisa Castaner, and Andres Sevtsuk created a computer model to predict the mix of businesses and places of interest found in a given neighborhood. The team used data from the Google Places API service to help identify movie theaters, gyms, and other businesses and map their locations. This approach has some limits-data from Places API tend to be restricted to places that are customer facing-but the data set nonetheless provides an extremely reliable source to study colocation patterns of neighborhood amenities.'),
  ('fa4ea2a2-6a3b-54e2-bbd8-6c6569e2a121', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Based on the text, the author would be most likely to disagree with which statement about vocal manipulation in hyperpop?', '["It is a symbol of the influence that hyperpop exerts on listeners’ sense of self.", "It represents changes to human experience brought about by technology.", "It is an aesthetic feature that has little or no social import.", "It confirms hyperpop’s ability to offset certain negative effects of digital technology."]'::jsonb, 8, 'A number of artists associated with hyperpop, a movement in electronic music that emerged in the 2010s, aggressively manipulate their recorded voice. The musician Laura Les, for example, shifts the pitch of her vocals to be much higher than that of her natural range. And even the hyperpop artists who don’t rely on pitch-shifting, such as Charli XCX, often distort their vocals using digital tools. Rather than being an arbitrary stylistic choice, hyperpop’s persistent modification of the voice functions as a commentary on how digital technology mediates human experience today.'),
  ('6e044aff-948b-53f7-925b-9ff82d5b87e4', '530c2438-5ab3-533a-a685-62a1b68437b5', 'According to the text, what did Brown and colleagues find and why does that occur?', '["Arizona pocket mice tend to be more active during periods of high lunar intensity than at other times because such conditions allow them to increase their foraging success without making them easier to detect.", "During periods of high lunar intensity, Arizona pocket mice reduce their activity because it is easier for predators to detect the mice in relatively bright conditions than it is for predators to detect three striped night monkeys in such conditions.", "Arizona pocket mice reduce their activity during periods of high lunar intensity because predators can more easily spot the mice in brighter conditions and such conditions do not benefit the mice enough to that risk.", "During periods of high lunar intensity three-striped night monkeys show a different behavioral response than Arizona pocket mice and many other nocturnal mammals do because the risks to three striped night monkeys under such conditions are greater."]'::jsonb, 9, 'Joel Brown and colleagues showed that high moonlight intensity inhibits the activity of the Arizona pocket mouse (Perognathus amplus), a finding explicable in terms of benefits and costs: greater lunar intensity may not enable the mice to increase foraging success enough to offset the higher chance of detection by predatory owls or hawks. Though many other nocturnal mammals respond to lunar intensity variations similarly to Arizona pocket mice, three-striped night monkeys (Aotus trivigatus) display the opposite pattern, as their heavy reliance on visual foraging results in a different balance of reward and risk.'),
  ('18af1958-27b0-5477-a824-f6d5205be75a', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which quotation from “The Yellow Wallpaper” most effectively illustrates the claim?', '["“This wallpaper has a kind of sub-pattern in a different shade, a particularly irritating one, for you can only see it in certain lights, and not clearly then.”", "“By moonlight / the moon shines in all night when there is a moon / I wouldn’t know it was the same paper.”", "“I’m really getting quite fond of the big room, all but that horrid [wall] paper.”", "“The color is repellant, almost revolting: a smouldering, unclean yellow, strangely faded by the slow turning sunlight.”"]'::jsonb, 10, '“The Yellow Wallpaper” is a 1892 short story by Charlotte Perkins Gilman. In the story, the narrator expresses mixed feelings about her surroundings: _____'),
  ('f554075e-b579-56bd-92f7-8ad80ff65d06', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice most effectively use data from the graph to complete the text?', '["most lizard species use about the same percentage of their maximal speed when escaping predation as they do when pursuing prey.", "multiple lizard species move at an average of less than 90% of their maximal speed while escaping predation.", "more lizard species use, on average, 90% -100% of their maximal speed while escaping predation than use any other percentage of their maximal speed.", "at least 4 lizard species use, on average, less than 100% of their maximal speed while pursuing prey."]'::jsonb, 11, '![figure](/q/dec23/001.webp)

It may seem that the optimal strategy for an animal pursuing prey or escaping predators is to move at maximal speed, but the energy expense of exploiting full speed capacity can disfavor such a strategy even in escape contexts, as evidenced by the fact that _____'),
  ('ef20951b-6f3a-5271-9268-199a3ca4397b', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice most logically completes the text?', '["attract glossy ibises to the area than they are to attract small white herons to the area.", "extend the average lifespan of small white herons already in the area than they are to attract a greater number of those birds to the area.", "decrease the area’s appeal to both small white herons and glossy ibises than they are to increase the appeal to other species.", "attract birds that don’t typically live in wetlands to the area than they are to attract small white herons or glossy ibises to the area."]'::jsonb, 12, 'The small white heron and the glossy ibis are long-legged birds that live in wetlands, like the Everglades in Florida. Laura D’Acunto and colleagues wanted to know how these birds choose an area in which to live. They looked at features of these birds’ habitats, such as how quickly water drains from the area and the amount of tree-canopy cover there is in the area. They found that small white herons prefer areas with extensive canopy cover, but this was not true for glossy ibises. The researchers therefore concluded that wetland-management strategies that increase the amount of tree canopy in potential wetland bird habitats are less likely to _____'),
  ('8dcb48c9-6bf3-5bb0-b4f6-1230444e5b8a', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice most logically completes the text?', '["hormone levels were higher in wild males than in captive male canaries.", "wild males and captive males usually exhibited very similar hormone levels.", "significant differences in hormone levels between individuals were found for both wild males and captive males.", "levels of androgen hormones during breeding season the higher in wild males than they are in captive males."]'::jsonb, 13, 'Biologists Rebecca M. Calisi-Rodriguez and George E. Bentley examined research on kestrels and canaries, both of which have been studied in the laboratory as well as in the wild, to see how studies’ settings might have affected their results. Lab studies are useful because they make it easy to control important variables, but kestrels’ surroundings can significantly affect their hormone levels. Therefore, it’s not altogether surprising that when Calisi-Rodriguez and Bentley examined studies of kestrels, they found that _____'),
  ('705e9492-8e60-586b-92a8-02bb38cb74d0', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the topological tapestries of Argentine textile artist Alexandra Kehayoglou are", "the Argentine textile artist Alexandra Kehayoglou creates topological tapestries that are", "when she creates her topological tapestries. Argentine textile artist Alexandra Kehayoglou makes them", "Alexandra Kehayoglou is an Argentine textile artist whose topological tapestries are"]'::jsonb, 14, 'Woven from recycled yarn and hand tufted using a carpet weaving technique passed down by the artist’s Turkish grandmother, _____ so lush and tactilely inviting that you are tempted to reach out and touch them.'),
  ('837126c3-a68d-56dd-b714-49beb3e67647', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["novelist Stephen Graham Jones", "novelist, Stephen Graham Jones,", "novelist. Stephen Graham Jones", "novelist Stephen Graham Jones,"]'::jsonb, 15, 'The editors of Home Ground: A Guide to the American Landscape turned to the _____ to craft the entry about “hueco,” a term referring to a water-retaining depression in a rock face.'),
  ('c15fdbbd-6fb3-589f-806f-b8180d12c261', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text so that if conforms to the conventions of Standard English?', '["Abbud and titled", "Abbud, titled", "Abbud titled", "Abbud. Titled"]'::jsonb, 16, 'Featured in The New Woman Behind the Camera (2021) is a photograph taken in 1935 by Karimeh _____ “Three Women,” Abbud’s image contributes to the exhibition’s goal of showcasing the diverse, innovative, often aesthetically daring work of female photographers from the 1920s through the 1950s.'),
  ('9f2fe60d-03bb-5552-bc26-6501b50cfff4', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["underlies", "is underlying", "underlie", "has been underlying"]'::jsonb, 17, 'In her 1983 book The Managed Heart: Commercialization of Human Feeling, sociologist Arlie Russell Hochschild first explored at length her conception of a “sociology of emotions”—the idea that the various cultural and ideological frameworks a person has internalized (class, gender, political affiliation, etc.) _____ each emotional reaction that person has within a situation.'),
  ('499fb06a-e50b-5f45-ac77-404d23700d18', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Switzerland, for example;", "Switzerland, for example,", "Switzerland. For example", "Switzerland: for example."]'::jsonb, 18, 'Photographer Mária Svarbová has reached audiences well beyond her home country of Slovakia. In 2020, her work was featured at the Alex Schlesinger Gallery in _____ the exhibited photographs, with their vivid pastel colors, overexposed tones, and mirrorlike symmetry, captivated audiences.'),
  ('aa8f0358-c164-5f9a-8d73-63e8d88d7e44', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["compiled,", "compiled", "compiled:", "compiled."]'::jsonb, 19, 'On February 1, 2018, Florida-based researchers Martha A. Scholl, Maoya Bassiouni, and Angel J. Torres-Sánchez _____ climate data from several sites in Puerto Rico’s Luquillo Mountains. At 12:00 a.m., the air temperature was 15.6°C at site CC1, the site with the highest elevation, and it had shifted to 16.2°C by 6:00 p.m.'),
  ('ed3601ab-546d-5429-8ff7-c4c07047d721', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["fertilizers. Containing", "fertilizers, containing", "fertilizers containing", "fertilizers, which contain"]'::jsonb, 20, 'In 2013, a study led by the researcher Laura A. Burkle investigated the relationship between grassland arthropod populations and agricultural _____ macronutrients like nitrogen, phosphorus, and potassium. Containing fertilizers boost the productivity of crops, potentially offering more nutrients for arthropods.'),
  ('7ad41757-5b67-557a-b006-b7648b784ac8', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text with the most logical transition?', '["Specifically,", "In conclusion,", "However,", "Nevertheless,"]'::jsonb, 21, 'The world’s first airplane, the 1903 Wright Flyer, was not very aerodynamic, as evidenced by its low lift-to-drag ratio of just 8.3:1. The Douglas DC-10 jet, like most modern aircraft, is far more aerodynamic. _____ its lift-to-drag ratio is more than twice that of the Wright Flyer.'),
  ('726ca8cf-284e-5aff-8fea-62c83fc6ae64', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text with the most logical transition?', '["Of course,", "Thus,", "Similarly.", "Furthermore."]'::jsonb, 22, 'Modernista architects championed nature in their designs. _____ the whimsical archways and ornate floral tilework of Casa Amatller, a Modernista private home designed by Josep Puig i Cadafalch, couldn’t exactly grow in a forest. Still, one sees natural influences in Puig i Cadafalch’s penchant for curves (rather than right angles) and plant- and animal-inspired flourishes.'),
  ('bdc11c70-16c1-53b7-b8d8-5bd1ec8b6d91', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text with the most logical transition?', '["Similarly,", "Nevertheless,", "For this reason,", "In other words,"]'::jsonb, 23, 'Before the first railroads were built in Australia, engineers warned against using multiple track widths across the continent. _____ regional officials couldn’t agree on a single-width system. Thus, railways in Queensland, like the Big Pineapple Railway, were made using narrow tracks, while those in Victoria were built with wide tracks.'),
  ('f20bf868-049a-5744-95df-3d3247d5dfce', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice completes the text with the most logical transition?', '["However,", "Moreover,", "Similarly,", "Accordingly,"]'::jsonb, 24, 'Legislators in Barbados are elected via a first-past-the-post electoral system. In this winner-take-all voting system, the seat is awarded to the candidate who receives not a majority but a plurality (i.e., greatest number) of votes. _____ if several popular candidates are vying for the same seat, it is possible for a candidate to win an election despite receiving less than 50% of the votes.'),
  ('6e820afb-749f-52d5-90bb-7a9ffe38f7dd', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice most effectively uses information from the given sentences to emphasize when she collected both of the samples?', '["While both specimens collected by Ynés Mexía are members of the same family, Erigeron maximus was found in Minas Gerais and Brickellia diffusa was found in Jalisco.", "Ynés Mexía collected a sample of Erigeron maximus in February of 1930, after collecting Brickellia diffusa in November of 1926.", "On February 1 in 1930, Ynés Mexía added a new specimen to her growing collection of botanical samples: Erigeron maximus of the Asteraceae family.", "Thousands of botanical samples collected by Ynés Mexía can now be found in one place: online at the C.V. Starr Virtual Herbarium."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Ynés Mexía was a Mexican American botanist.
Between 1917 and 1938, she collected over 150,000 botanical samples throughout the Americas. She collected a sample of Erigeron maximus in Minas Gerais, Brazil, on February 1, 1930. She collected a sample of Brickellia diffusa in Jalisco, Mexico, on November 23, 1926.
These specimens are members of the Asteraceae family.
They can now be viewed online at the C.V. Starr Virtual Herbarium.'),
  ('0a934645-4c2e-53b4-a979-64d26766f59f', '530c2438-5ab3-533a-a685-62a1b68437b5', 'The student wants to emphasize the 2020 population of Acaxochitlán. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["As a municipality in Hidalgo, Acaxochitlán is responsible for providing public services to its population.", "Home to 40,583 people, the governmental region was responsible for providing water treatment to its population in 2010.", "As of 2020, Acaxochitlán was one of 84 municipalities in Hidalgo, Mexico.", "In 2020, the municipality of Acaxochitlán had a population of 46,065."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Acaxochitlán is a municipality in the state of Hidalgo, Mexico.
Municipalities are governmental regions responsible for providing many public services to their residents.
One service they provide is water treatment.
Acaxochitlán’s population was 46,065 in 2020.
Its population was 40,583 in 2010.
Hidalgo is divided into 84 municipalities.'),
  ('8aba4084-c11a-5478-9b1f-cbcfdeecd2e2', '530c2438-5ab3-533a-a685-62a1b68437b5', 'Which choice most effectively uses information from the given sentences to make and support a generalization about symbols on flags?', '["Grenada’s flag includes a clove of nutmeg, a symbol that is important to that country’s national identity.", "Vexillology is the study of flags: accordingly, vexillologists are interested in flags from around the world.", "The flags of some countries include symbols of plants: Grenada’s, for example, includes a clove of nutmeg.", "Many countries feature symbols on their flags, and the study of these designs is known as vexillology."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Vexillology is the study of flags.
The flags of many countries include symbols like animals, plants, or landforms.
These symbols often represent an aspect of the region’s history, culture, or landscape. The flag of Grenada includes a clove of nutmeg.
The flag of Andorra includes a cow.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('84afe7fa-c028-5235-9418-c8fb1f268346', 3, null, '**Choice D is correct.** The sentence states that tenrecs "share basic _____ true hedgehogs, including protective spines, pointed snouts, and small body size," so the blank needs a noun phrase that indicates a set of traits in common; "similarities with" precisely expresses that the two groups have features in common.
**Choice A is incorrect.** "examples of" would indicate that tenrecs are instances of true hedgehogs, which contradicts the opening clause "Though not closely related."
**Choice B is incorrect.** "concerns about" makes no sense semantically: the sentence is describing physical traits, not worries or issues.
**Choice C is incorrect.** "indications of" suggests signs or evidence of true hedgehogs rather than shared traits; it is less precise and doesn’t fit as naturally as "similarities with."
**Faster approach:** For sentence-completion items about shared traits, immediately eliminate choices implying identity or affect (e.g., "examples of," "concerns about") and pick the option that denotes shared features (e.g., "similarities with").'),
  ('e17644d2-af23-5771-aa82-9156464bb27a', 2, null, '**Choice C is correct.** The sentence sets up a contrast: although Nancy Bird-Walton accomplished much, her place in historical memory is being compared to that of a clear “first” who “will always be remembered.” The phrase “will always be remembered” implies certainty and permanence, so the writer needs a word indicating the opposite for Bird-Walton’s memory. “Uncertain” precisely expresses that her place in memory is less secure or lasting than the memorable first, so it best completes the comparison.
**Choice A is incorrect.** “Deserving” does not fit the contrast; the sentence discusses how securely each woman is remembered, not whether Bird-Walton merits recognition.
**Choice B is incorrect.** “Conspicuous” means noticeable or prominent, which would contradict the idea that Bird-Walton is less likely to be remembered than the famous “first.”
**Choice D is incorrect.** “Enduring” means long-lasting and would make Bird-Walton’s memory similar to the other woman’s; it fails to reflect the intended contrast suggested by “but” and “will always be remembered.”
**Faster approach:** Spot the contrast marker (“but”) and the phrase indicating permanence (“will always be remembered”), then pick the choice that expresses the opposite quality (uncertain) to complete the comparison.'),
  ('140d5860-b285-57bd-9133-dd8936776207', 3, null, '**Choice D is correct.** The sentence says that humanoid features like bipedal locomotion make interaction easier by increasing comfort; to "buttress" means to support or strengthen, so "help to buttress people’s feelings of comfort" precisely conveys that these features reinforce or bolster comfort.
**Choice A is incorrect.** "Mitigate" means to make something less severe; it would imply reducing feelings of comfort, which is the opposite of the intended meaning.
**Choice B is incorrect.** "Constrict" means to tighten or limit, which would suggest decreasing or restricting comfort rather than supporting it.
**Choice C is incorrect.** "Repudiate" means to reject or disown; that does not fit with the idea of a feature helping interaction by increasing comfort.
**Faster approach:** Quickly consider each option’s basic meaning and test it in the phrase "help to ___ people’s feelings of comfort"—eliminate verbs that imply reduction or rejection, leaving the one that means support.'),
  ('193a8118-31a7-54ea-bf52-35edec818217', 3, null, '**Choice D is correct.** The sentence contrasts two ideas: scholarship has undermined claims about Ibn Rushd’s relationship to other Muslim philosophers, but it remains indisputable that his geographic location affected who could access his works. Saying his works were “inconsequential to” other philosophers means they mattered little to contemporaries—this fits the contrast because even if his influence was minimal, his distance explains limited availability. The phrase precisely expresses lack of impact, which is why scholars would challenge claims that he mattered to others.
**Choice A is incorrect.** “Controversial among” means his works provoked dispute; that doesn’t match the following clause about geographic availability and doesn’t create the intended contrast between disputed scholarly claims and an indisputable fact about access.
**Choice B is incorrect.** “Antagonistic toward” implies his works were hostile to other philosophers, which changes the meaning from whether they mattered or were influenced by him and is not supported by the sentence’s focus on availability and influence.
**Choice C is incorrect.** “Imitated by” asserts that other philosophers copied him; the sentence says scholarship has undermined such claims, so using a phrase that affirms imitation would contradict the first clause rather than provide the contrasting idea about his limited availability.
**Faster approach:** Identify the sentence’s logical contrast (scholarly dispute vs. an indisputable fact). Then test each option to see which establishes that contrast—eliminate choices that change the sentence’s focus (controversy, hostility, imitation) and keep the one that expresses lack of influence: “inconsequential to.”'),
  ('b9f786e9-e2d9-5f91-9ff8-b84372069eee', 1, null, '**Choice B is correct.** The passage begins by defining "community science" (identifying an approach to research), then gives three specific benefits of that approach (greater public awareness, youth learning experiences, increased data), and finally cites a specific study by Grace Herzel that used community science. This matches the sequence described in choice B.
**Choice A is incorrect.** The passage does not present the study’s actual results; it only says the approach was essential to the study and that the study included findings from many participants, not specific study findings.
**Choice C is incorrect.** The passage does not discuss the development or history of the collaboration nor propose future projects; it simply defines the approach, lists benefits, and gives an example study.
**Choice D is incorrect.** The passage does not argue for a new approach or report on public opinion; it neutrally describes community science, lists benefits, and mentions a study that used it rather than making an argumentative case.
**Faster approach:** Scan for the first sentence to identify the topic, then note whether middle sentences list benefits or background, and check the final sentence for an example—match that sequence to the answer choices.'),
  ('381acc39-fc64-522f-82b5-7d81eca07112', 1, null, '**Choice B is correct.** Text 1 explicitly states that Wahbi and colleagues "did not take" the crucial step of excluding all pathways other than the CMN, so the author of Text 1 would answer No. Text 2 explains that allowing hyphae also permits liquids and therefore cannot ensure exclusion of non-CMN pathways; that logic implies the author of Text 2 would also answer No for a study that failed to control pathways (as Wahbi’s did). Both authors thus agree that Wahbi and colleagues did not effectively exclude other nutrient pathways.
**Choice A is incorrect.** The authors disagree: Text 1 presents Xiao’s barriers as sufficient, while Text 2 argues those barriers could still allow liquid transfer and so are not sufficient.
**Choice C is incorrect.** Neither text addresses whether plants that transfer nutrients root-to-root also transmit via a CMN; no evidence is provided to answer this.
**Choice D is incorrect.** Neither author claims there exists a barrier material that blocks roots and liquids while allowing fungal strands; the texts discuss specific experimental barriers but do not assert such a material is available.
**Faster approach:** Scan each text for explicit statements about what each study did or did not control; match those statements to the choices and eliminate any choice not directly addressed by both passages.'),
  ('d0ad022a-e02e-5a8a-ac57-da9b9f1cb412', 0, null, '**Choice A is correct.** The passage explicitly notes a limitation of the researchers'' method: "data from Places API tend to be restricted to places that are customer facing." Because the data set emphasizes customer-facing businesses, it may omit other kinds of amenities, so conclusions might not reflect all neighborhood amenities.
**Choice B is incorrect.** The passage does not say the method misidentifies neighborhood boundaries; it discusses the types of places represented in the data, not geographic boundary accuracy.
**Choice C is incorrect.** The passage does not describe the method as relying on untested advancements from other fields; it attributes the method to using Google Places API data and modeling colocation patterns.
**Choice D is incorrect.** The passage mentions a restriction in the kinds of places included, not that the data are likely to be outdated.
**Faster approach:** Scan the sentence that begins with "This approach has some limits" to find the stated drawback; the answer will restate that limitation in simpler terms.'),
  ('fa4ea2a2-6a3b-54e2-bbd8-6c6569e2a121', 2, null, '**Choice C is correct.** The passage explicitly rejects the idea that vocal manipulation is merely an arbitrary aesthetic: it states that hyperpop’s persistent modification of the voice “functions as a commentary on how digital technology mediates human experience today,” which attributes social and cultural significance to the practice rather than saying it has little or no social import.
**Choice A is incorrect.** The passage supports the idea that vocal manipulation symbolizes technology’s effect on human experience, so it does not conflict with vocal manipulation influencing listeners’ sense of self.
**Choice B is incorrect.** This choice restates the passage’s claim that the manipulation represents changes to human experience brought about by technology.
**Choice D is incorrect.** The passage describes vocal modification as commentary on technology’s mediation of experience but does not assert that hyperpop offsets negative effects of technology; however, that is not directly contradicted by the passage the way C is.
**Faster approach:** Look for language stating purpose or function (e.g., "functions as a commentary") and eliminate any choice that claims the opposite (saying it’s insignificant).'),
  ('6e044aff-948b-53f7-925b-9ff82d5b87e4', 2, null, '**Choice C is correct.** The passage states that "high moonlight intensity inhibits the activity of the Arizona pocket mouse" and explains this by saying greater lunar intensity "may not enable the mice to increase foraging success enough to offset the higher chance of detection by predatory owls or hawks." Choice C accurately paraphrases both the finding (reduced activity during bright moonlight) and the reason (brighter conditions increase predator detection while not sufficiently improving foraging).
**Choice A is incorrect.** It states the mice are more active during high lunar intensity and gives the opposite causal claim; the passage says activity is inhibited, not increased.
**Choice B is incorrect.** Although it correctly notes reduced activity, its rationale compares detectability of mice to three-striped night monkeys, which is not the passage’s stated reason for the mice’s behavior.
**Choice D is incorrect.** The passage does say three-striped night monkeys respond differently, but it attributes that difference to monkeys'' reliance on visual foraging (a different balance of reward and risk), not to greater risks to the monkeys under bright conditions.
**Faster approach:** Scan for the sentence that states the main finding and its explanation—identify the phrase about activity being "inhibited" and the clause about not offsetting increased detection to find the correct answer quickly.'),
  ('18af1958-27b0-5477-a824-f6d5205be75a', 2, null, '**Choice C is correct.** The line “I’m really getting quite fond of the big room, all but that horrid [wall] paper.” directly expresses mixed feelings by pairing a positive reaction (“quite fond”) with an immediate negative qualification (“all but that horrid … paper”), which matches the claim that the narrator has mixed feelings about her surroundings.
**Choice A is incorrect.** That quotation emphasizes irritation and difficulty seeing the pattern — a negative reaction — but does not pair it with any positive feeling, so it does not show mixed feelings.
**Choice B is incorrect.** The moonlight observation describes a change in appearance and perhaps fascination, but it does not pair a clear positive and negative response in the same statement.
**Choice D is incorrect.** This description is wholly negative ("repellant, almost revolting") and therefore does not illustrate mixed feelings.
**Faster approach:** Scan for contrast words or structures (but, however, yet, except) that signal simultaneous positive and negative reactions; such constructions usually indicate mixed feelings and quickly identify the correct choice.'),
  ('f554075e-b579-56bd-92f7-8ad80ff65d06', 1, null, '**Choice B is correct.** The graph shows several light bars (escaping) in bins below 90% — specifically nonzero counts in the 40–49, 50–59, 60–69, 70–79, and 80–89 bins — so multiple lizard species average less than 90% of maximal speed when escaping. This supports the passage’s claim that energy costs can prevent animals from using full speed even when escaping.
**Choice A is incorrect.** The dark (pursuing) and light (escaping) bars are not generally the same height across bins, so species do not use about the same percentage for both behaviors.
**Choice C is incorrect.** Although the escaping bar in 90–100 is the tallest single bar, that statement implies most use 90–100% which would contradict the passage; moreover the presence of many escaping species in lower bins shows substantial use below 90%.
**Choice D is incorrect.** Choice D refers to pursuing behavior and ‘‘less than 100%’’ — while true that at least four pursuing counts fall below 100%, this choice does not address escaping behavior and therefore does not support the passage’s point about escape energy trade-offs.
**Faster approach:** Scan the legend to identify which bars correspond to escaping, then compare heights across the percent bins to see whether many escaping bars fall below the top (90–100) bin; choose the option that describes that distribution.'),
  ('ef20951b-6f3a-5271-9268-199a3ca4397b', 0, null, '**Choice A is correct.** The passage says small white herons prefer areas with extensive canopy cover but glossy ibises do not. Therefore, management strategies that increase canopy would be less likely to attract glossy ibises than they would be to attract small white herons; this directly matches the comparative structure of choice A.
**Choice B is incorrect.** The passage discusses habitat preference and attraction, not lifespan or effects on individuals already present, so this comparison is unsupported.
**Choice C is incorrect.** The passage gives no evidence that increased canopy would decrease appeal to both species or increase appeal to other species; it only contrasts the two named species’ preferences.
**Choice D is incorrect.** The passage does not suggest that increasing canopy would attract non-wetland birds, only that it differentially affects small white herons and glossy ibises.
**Faster approach:** Identify the specific contrast in the passage (herons prefer canopy; ibises do not), then choose the answer that restates that contrast directly—eliminate options that introduce unrelated effects.'),
  ('8dcb48c9-6bf3-5bb0-b4f6-1230444e5b8a', 3, null, '**Choice D is correct.** The passage states that kestrels’ surroundings can significantly affect their hormone levels; that immediately predicts a systematic difference between wild and captive birds. The most specific completion that matches this prediction is that androgen levels during the breeding season are higher in wild males than in captive males, which explains how environment (wild vs. captive) alters hormone measurements.
**Choice A is incorrect.** It compares kestrels to canaries, introducing a different species not implied by the sentence; the passage concerns differences caused by setting for kestrels, not comparisons across species.
**Choice B is incorrect.** It asserts wild and captive males usually have very similar hormone levels, which contradicts the passage’s claim that surroundings can significantly affect hormone levels.
**Choice C is incorrect.** It describes individual variation within groups (differences between individuals in each group) rather than systematic differences between wild and captive kestrels driven by setting, so it does not follow from the preceding sentence.
**Faster approach:** Look for the answer that matches the cause-effect in the lead sentence (environment affects hormones) and eliminate choices that contradict that effect or introduce irrelevant species or comparisons.'),
  ('705e9492-8e60-586b-92a8-02bb38cb74d0', 0, null, '**Choice A is correct.** The introductory participial phrase "Woven from recycled yarn and hand tufted..." must modify the noun that immediately follows. Choice A supplies the plural subject "the topological tapestries of Argentine textile artist Alexandra Kehayoglou," so the phrase correctly describes the tapestries: "...the topological tapestries ... are so lush... that you are tempted to reach out and touch them." The plural subject also provides a clear antecedent for "them."
**Choice B is incorrect.** It makes the artist the subject modified by the participial phrase, creating a misplaced modifier: the artist was not woven and tufted, her tapestries were.
**Choice C is incorrect.** It produces a sentence fragment and awkward word order and fails to place the tapestries as the noun modified by the opening phrase.
**Choice D is incorrect.** Like B, it makes the artist (not the tapestries) the immediate subject of the participial phrase, creating a misplaced modifier.
**Faster approach:** Immediately after a participial phrase, expect the noun it modifies; choose the answer that supplies that noun as the sentence subject (often plural if a plural pronoun like "them" appears later).'),
  ('837126c3-a68d-56dd-b714-49beb3e67647', 0, null, '**Choice A is correct.** The phrase identifies which novelist the editors consulted, so the name is a restrictive modifier that should not be set off with commas. "novelist Stephen Graham Jones" smoothly completes the sentence: "The editors ... turned to the novelist Stephen Graham Jones to craft the entry..." which conforms to Standard English.
**Choice B is incorrect.** The commas make "Stephen Graham Jones" a nonrestrictive appositive; that would imply the novelist is already identified and the commas are unnecessary and change the intended meaning.
**Choice C is incorrect.** The period creates a sentence fragment and disrupts the flow: "novelist. Stephen Graham Jones to craft..." is ungrammatical.
**Choice D is incorrect.** The trailing comma after the name is unnecessary and creates a punctuation error before the infinitive phrase "to craft the entry."
**Faster approach:** Read the sentence aloud without punctuation; if the name is essential identifying information, use no commas (restrictive appositive).'),
  ('c15fdbbd-6fb3-589f-806f-b8180d12c261', 3, null, '**Choice D is correct.** Placing a period after "Abbud" makes the first clause a complete sentence: "Featured in The New Woman Behind the Camera (2021) is a photograph taken in 1935 by Karimeh Abbud." Beginning the next sentence with the participial phrase "Titled ''Three Women,''" correctly modifies the subject that follows ("Abbud’s image") and avoids a comma splice. The result is two grammatically complete, clearly connected sentences.
**Choice B is incorrect.** "Abbud, titled" would insert a nonrestrictive phrase but, as given, leaves the sentence with a comma connecting two independent clauses and creates a comma splice.
**Choice A is incorrect.** "Abbud and titled" is ungrammatical here because "and titled" awkwardly joins modifiers and does not create a properly punctuated, single or compound clause.
**Choice C is incorrect.** "Abbud titled" implies that Abbud is the agent who titled something (active voice) and also fails to provide correct punctuation to set off the title; it changes the intended meaning and yields an awkward construction.
**Faster approach:** When a phrase like "titled ''...''," modifies a noun already in a preceding clause, check whether a period to start a new sentence (turning the phrase into a fronted modifier) removes any comma-splice or awkward modifier placement. If it does, choose the punctuation that makes two clear sentences.'),
  ('9f2fe60d-03bb-5552-bc26-6501b50cfff4', 2, null, '**Choice C is correct.** The subject of the verb is "the various cultural and ideological frameworks," which is plural, so it requires a plural verb form. The simple present plural verb "underlie" correctly matches the plural subject and expresses a general, habitual relationship—these frameworks generally form the basis for each emotional reaction. "Underlie" fits the sentence’s meaning and conforms to Standard English subject-verb agreement.
**Choice A is incorrect.** "Underlies" is singular and does not agree with the plural subject "frameworks."
**Choice B is incorrect.** "Is underlying" is a present progressive form that implies an ongoing action; the sentence calls for a general, habitual statement rather than a continuous process.
**Choice D is incorrect.** "Has been underlying" is present perfect progressive (or perfect) and suggests a continuous action extending from the past to now, which is unnecessary and less idiomatic than the simple present here.
**Faster approach:** Identify the head noun ("frameworks") to determine plural vs. singular, then choose the matching verb form in simple present for a general truth—so pick the plural simple present "underlie."'),
  ('499fb06a-e50b-5f45-ac77-404d23700d18', 0, null, '**Choice A is correct.** The sentence contains two independent clauses: "her work was featured...in Switzerland" and "the exhibited photographs...captivated audiences." A semicolon is needed to join them when a conjunctive adverb ("for example") introduces the second clause; choice A supplies that semicolon and sets off "for example" as a parenthetical. The result reads correctly: "...in Switzerland, for example; the exhibited photographs...captivated audiences."
**Choice B is incorrect.** Setting "for example" off only with commas leaves two independent clauses separated by a comma, creating a comma splice.
**Choice C is incorrect.** A period before "For example" could work, but this choice omits the required comma after "For example," producing "For example the exhibited...," which is incorrect punctuation.
**Choice D is incorrect.** A colon before "for example" plus a period after it produces a fragment and breaks the flow; it does not properly connect the two independent clauses.
**Faster approach:** Identify whether each portion is an independent clause; if so and a conjunctive adverb (like "for example") begins the second clause, use a semicolon before and a comma after the conjunctive adverb.'),
  ('aa8f0358-c164-5f9a-8d73-63e8d88d7e44', 1, null, '**Choice B is correct.** The sentence continues after the verb phrase with a complete independent clause describing specific temperatures, so the verb should be followed by a single space and no extra punctuation; a plain comma is unnecessary and a colon or period would either create a sentence boundary or signal a list, neither of which is appropriate here. Writing "compiled" with nothing after it (just a space) correctly integrates the introductory phrase "On February 1, 2018, Florida-based researchers Martha A. Scholl, Maoya Bassiouni, and Angel J. Torres-Sánchez compiled climate data from several sites in Puerto Rico’s Luquillo Mountains." and then continues the same sentence with the time-and-temperature clause.
**Choice A is incorrect.** A comma after "compiled" would create an unnecessary and incorrect parenthetical break between the verb and its direct object "climate data," disrupting the sentence flow.
**Choice C is incorrect.** A colon after "compiled" would wrongly signal that what follows is a list or explanation directly deriving from "compiled," but the following clause simply continues the sentence with additional information rather than serving as a formal elaboration that requires a colon.
**Choice D is incorrect.** A period after "compiled" would create a sentence fragment because the subsequent clause ("At 12:00 a.m., the air temperature...") is clearly intended to be part of the same sentence and depends on the introductory context.
**Faster approach:** Read the full sentence to see whether the clause after the verb is a continuation of the same sentence; if it is, choose the option with no extra punctuation. This eliminates choices with commas, colons, or periods.'),
  ('ed3601ab-546d-5429-8ff7-c4c07047d721', 2, null, '**Choice C is correct.** The phrase "agricultural fertilizers containing macronutrients like nitrogen, phosphorus, and potassium" correctly places the participial modifier immediately after the noun it describes, creating a grammatical restrictive modifier that specifies which fertilizers are meant.
**Choice A is incorrect.** A period before "Containing" leaves the next sentence as a fragment ("Containing fertilizers..."), which is ungrammatical.
**Choice B is incorrect.** The comma plus "containing" makes a nonessential clause, which is unnecessary here and still leaves the following sentence as a fragment.
**Choice D is incorrect.** "Which contain" makes a nonrestrictive clause (implying all agricultural fertilizers contain those macronutrients) and is less precise than the restrictive modifier required; it also does not resolve the fragment in the next sentence.
**Faster approach:** Attach modifiers directly to the noun they describe; prefer a restrictive participial phrase (no comma) when you need to specify which items are meant and immediately eliminate choices that create sentence fragments.'),
  ('7ad41757-5b67-557a-b006-b7648b784ac8', 0, null, '**Choice A is correct.** The sentence that follows offers a specific piece of evidence that supports the claim that the DC-10 is far more aerodynamic; "Specifically," signals that the writer is about to give that precise supporting detail (the lift-to-drag ratio being more than twice that of the Wright Flyer).
**Choice B is incorrect.** "In conclusion," signals a final summary or wrap-up, which is inappropriate here because the sentence provides supporting detail rather than ending the discussion.
**Choice C is incorrect.** "However," indicates a contrast or contradiction with the previous statement; the second sentence actually reinforces the claim that the DC-10 is more aerodynamic, so a contrasting connector is wrong.
**Choice D is incorrect.** "Nevertheless," also signals contrast or concession; because the second sentence supplies confirming evidence rather than conceding a point, this transition does not fit.
**Faster approach:** Identify whether the added sentence supports, contrasts, or concludes the previous one; then pick a transition that matches (support = "Specifically," or "For example,"; contrast = "However," or "Nevertheless,"; conclusion = "In conclusion,").'),
  ('726ca8cf-284e-5aff-8fea-62c83fc6ae64', 0, null, '**Choice A is correct.** The sentence that follows offers a natural limitation or obvious contrast to the preceding general statement that Modernista architects championed nature; "Of course," signals that what follows is an expected qualification: the whimsical archways and ornate floral tilework couldn’t literally grow in a forest. This fits the contrast introduced by the next sentence, "Still, one sees natural influences...," which acknowledges the limitation while maintaining the main point.
**Choice B is incorrect.** "Thus" indicates a logical result, but the sentence is a qualification (what cannot happen), not a consequence of the previous claim.
**Choice C is incorrect.** "Similarly" would indicate another example of resemblance, but the sentence actually points out an impossibility that contrasts with the idea of nature being embodied literally.
**Choice D is incorrect.** "Furthermore" would add information that supports the prior statement, whereas the sentence provides a conciliatory or corrective note rather than additional support.
**Faster approach:** Identify whether the next clause contrasts, concludes, adds, or provides an example—match to contrast words (e.g., "Of course,"/"However,"), result words ("Thus"), addition words ("Furthermore"), or similarity words ("Similarly").'),
  ('bdc11c70-16c1-53b7-b8d8-5bd1ec8b6d91', 1, null, '**Choice B is correct.** The passage states that engineers warned against multiple track widths, but the next clause reports that regional officials couldn’t agree on a single system; that outcome contrasts with the warning, so a contrastive transition like “Nevertheless,” logically connects the sentences. The final sentence shows the consequence of that disagreement, reinforcing the contrast.
**Choice A is incorrect.** “Similarly,” indicates agreement or repetition of an idea, but the second clause describes a failure to follow the engineers’ advice, which is the opposite of similarity.
**Choice C is incorrect.** “For this reason,” would suggest the disagreement was the cause of the engineers’ warning, but the order of events in the passage is the opposite: engineers warned first and officials later failed to agree.
**Choice D is incorrect.** “In other words,” signals a restatement or clarification of the previous idea, but the second clause presents a new, contrasting fact rather than a rephrasing.
**Faster approach:** Identify whether the second clause contrasts, supports, or restates the first; pick a transition that matches that relationship (contrast → “Nevertheless,” support → “For this reason,” restatement → “In other words,” similarity → “Similarly,”).'),
  ('f20bf868-049a-5744-95df-3d3247d5dfce', 3, null, '**Choice D is correct.** The sentence that follows explains a logical consequence of the plurality rule: when several candidates split the vote, the winner can have less than 50% of the votes. "Accordingly," signals that what follows is a result or consequence of the previous statement, so it fits the relationship between the two clauses.
**Choice A is incorrect.** "However," indicates a contrast, but the second clause does not contradict the first; it explains a direct consequence of awarding seats by plurality.
**Choice B is incorrect.** "Moreover," adds an additional point, but the second clause is not merely an additional fact — it follows as a consequence of the plurality rule.
**Choice C is incorrect.** "Similarly," suggests a comparison to something else, which does not match the causal relationship expressed between the two sentences.
**Faster approach:** For transition questions, identify whether the next clause is showing contrast, addition, comparison, or consequence; then pick the transition word that signals that exact logical relationship (here, consequence → "Accordingly").'),
  ('6e820afb-749f-52d5-90bb-7a9ffe38f7dd', 1, null, '**Choice B is correct.** The sentence directly uses the dates given in the notes to emphasize timing: Ynés Mexía collected Erigeron maximus in February 1930 and collected Brickellia diffusa in November 1926, and it also clarifies their chronological order (“after”), which is precisely about when the two samples were collected.
**Choice A is incorrect.** It emphasizes locations (Minas Gerais and Jalisco) rather than the timing of the collections, so it does not answer the prompt’s focus on when the samples were collected.
**Choice C is incorrect.** It mentions the date for only Erigeron maximus (February 1, 1930) and therefore fails to emphasize when both samples were collected.
**Choice D is incorrect.** It discusses where the specimens can be viewed (the virtual herbarium) rather than when they were collected.
**Faster approach:** Scan choices for explicit date language; the option that names both dates (and their order) answers a question about timing.'),
  ('0a934645-4c2e-53b4-a979-64d26766f59f', 3, null, '**Choice D is correct.** It directly and clearly states the 2020 population figure from the notes: "In 2020, the municipality of Acaxochitlán had a population of 46,065," which emphasizes the 2020 population without adding unrelated details.
**Choice A is incorrect.** It discusses the municipality’s responsibility for public services but does not mention any population numbers or the year 2020, so it fails to emphasize the 2020 population.
**Choice B is incorrect.** It gives the 2010 population (40,583) and mentions water treatment, so it emphasizes the wrong year and includes extraneous information.
**Choice C is incorrect.** It mentions 2020 but emphasizes that Acaxochitlán is one of 84 municipalities rather than giving or highlighting the 2020 population figure.
**Faster approach:** Look for the answer choice that reproduces the exact year and population number from the notes—pick the option that explicitly states "2020" and "46,065."'),
  ('8aba4084-c11a-5478-9b1f-cbcfdeecd2e2', 2, null, '**Choice C is correct.** The sentence makes a supported generalization about symbols on flags ("The flags of some countries include symbols of plants") and then immediately uses a specific example from the notes ("Grenada’s, for example, includes a clove of nutmeg"), directly tying the general statement to the provided evidence. This both states a general claim and supports it with the student’s observation about Grenada, matching the task of using information to make and support a generalization.
**Choice A is incorrect.** Although it correctly reports that Grenada’s flag includes a clove of nutmeg, it asserts that the symbol is "important to that country’s national identity"—a stronger interpretive claim not supported by the given notes, which only say the symbol represents aspects like history, culture, or landscape generally.
**Choice B is incorrect.** This restates the definition of vexillology and its implication but does not make a generalization about symbols on flags or use the specific evidence about flag symbols (animals, plants, landforms) to support such a generalization.
**Choice D is incorrect.** While it links the existence of symbols on flags to the term vexillology, it awkwardly combines two facts without using a specific example from the notes to support a generalization; the choice fails to use the provided examples (like Grenada’s nutmeg or Andorra’s cow) as supporting evidence.
**Faster approach:** For synthesis questions, look for the answer that pairs a clear general statement with an explicit example from the notes; scan choices for the one that contains both a generalization and a directly cited example.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
